    optimizedSolution: {
      explanation: "Sliding window tracking 'have' vs 'need' (distinct satisfied chars). Expand right; when window valid, shrink left to minimize. O(N+M).",
      timeComplexity: "O(N+M)",
      spaceComplexity: "O(N+M)",
      code: {
        python: `class Solution:
    def minWindow(self, s, t):
        from collections import Counter
        need=Counter(t)
        have,total=0,len(need)
        win={}
        bestLen,bestL=float('inf'),0
        left=0
        for right,ch in enumerate(s):
            win[ch]=win.get(ch,0)+1
            if ch in need and win[ch]==need[ch]: have+=1
            while have==total:
                if right-left+1<bestLen: bestLen=right-left+1; bestL=left
                lc=s[left]; win[lc]-=1
                if lc in need and win[lc]<need[lc]: have-=1
                left+=1
        return "" if bestLen==float('inf') else s[bestL:bestL+bestLen]`,
        javascript: `function minWindow(s,t) {
    const need={},win={};
    for(const c of t) need[c]=(need[c]||0)+1;
    let have=0,total=Object.keys(need).length,l=0,bestLen=Infinity,bestL=0;
    for(let r=0;r<s.length;r++) {
        win[s[r]]=(win[s[r]]||0)+1;
        if(need[s[r]]&&win[s[r]]===need[s[r]]) have++;
        while(have===total) {
            if(r-l+1<bestLen){bestLen=r-l+1;bestL=l;}
            win[s[l]]--;
            if(need[s[l]]&&win[s[l]]<need[s[l]]) have--;
            l++;
        }
    }
    return bestLen===Infinity?"":s.slice(bestL,bestL+bestLen);
}`,
        typescript: `function minWindow(s: string, t: string): string {
    const need: Record<string,number>={}, win: Record<string,number>={};
    for(const c of t) need[c]=(need[c]||0)+1;
    let have=0,total=Object.keys(need).length,l=0,bestLen=Infinity,bestL=0;
    for(let r=0;r<s.length;r++) {
        win[s[r]]=(win[s[r]]||0)+1;
        if(need[s[r]]&&win[s[r]]===need[s[r]]) have++;
        while(have===total) {
            if(r-l+1<bestLen){bestLen=r-l+1;bestL=l;}
            win[s[l]]--;
            if(need[s[l]]&&win[s[l]]<need[s[l]]) have--;
            l++;
        }
    }
    return bestLen===Infinity?"":s.slice(bestL,bestL+bestLen);
}`,
        cpp: `class Solution {
public:
    string minWindow(string s, string t) {
        unordered_map<char,int> need,win;
        for(char c:t) need[c]++;
        int have=0,total=need.size(),l=0,bestLen=INT_MAX,bestL=0;
        for(int r=0;r<s.size();r++) {
            win[s[r]]++;
            if(need.count(s[r])&&win[s[r]]==need[s[r]]) have++;
            while(have==total) {
                if(r-l+1<bestLen){bestLen=r-l+1;bestL=l;}
                win[s[l]]--;
                if(need.count(s[l])&&win[s[l]]<need[s[l]]) have--;
                l++;
            }
        }
        return bestLen==INT_MAX?"":s.substr(bestL,bestLen);
    }
};`,
        java: `class Solution {
    public String minWindow(String s, String t) {
        Map<Character,Integer> need=new HashMap<>(),win=new HashMap<>();
        for(char c:t.toCharArray()) need.merge(c,1,Integer::sum);
        int have=0,total=need.size(),l=0,bestLen=Integer.MAX_VALUE,bestL=0;
        for(int r=0;r<s.length();r++) {
            char c=s.charAt(r); win.merge(c,1,Integer::sum);
            if(need.containsKey(c)&&win.get(c).equals(need.get(c))) have++;
            while(have==total) {
                if(r-l+1<bestLen){bestLen=r-l+1;bestL=l;}
                char lc=s.charAt(l); win.merge(lc,-1,Integer::sum);
                if(need.containsKey(lc)&&win.get(lc)<need.get(lc)) have--;
                l++;
            }
        }
        return bestLen==Integer.MAX_VALUE?"":s.substring(bestL,bestL+bestLen);
    }
}`
      }
    }
