    optimizedSolution: {
      explanation: "DFS/BFS traversal visiting each node once. Mark visited to avoid cycles in graphs.",
      timeComplexity: "O(N) or O(V+E)",
      spaceComplexity: "O(N)",
      code: {
        python: `class Solution:
    def solve(self, root):
        if not root: return []
        res=[]; queue=[root]
        while queue:
            node=queue.pop(0)
            res.append(node.val)
            if node.left: queue.append(node.left)
            if node.right: queue.append(node.right)
        return res`,
        javascript: `function solve(root){if(!root)return[];const res=[],q=[root];while(q.length){const n=q.shift();res.push(n.val);if(n.left)q.push(n.left);if(n.right)q.push(n.right);}return res;}`,
        typescript: `function solve(root: any): number[]{if(!root)return[];const res: number[]=[],q=[root];while(q.length){const n=q.shift();res.push(n.val);if(n.left)q.push(n.left);if(n.right)q.push(n.right);}return res;}`,
        cpp: `class Solution{
public:
    vector<int> solve(TreeNode*root){if(!root)return{};vector<int>res;queue<TreeNode*>q;q.push(root);while(!q.empty()){auto n=q.front();q.pop();res.push_back(n->val);if(n->left)q.push(n->left);if(n->right)q.push(n->right);}return res;}
};`,
        java: `class Solution{
    public List<Integer> solve(TreeNode root){if(root==null)return new ArrayList<>();List<Integer>res=new ArrayList<>();Queue<TreeNode>q=new LinkedList<>();q.offer(root);while(!q.isEmpty()){TreeNode n=q.poll();res.add(n.val);if(n.left!=null)q.offer(n.left);if(n.right!=null)q.offer(n.right);}return res;}
}`
      }
    }
