      code: {
        python: `class Solution:
    def solve(self, nums):
        n=len(nums); res=[-1]*n
        for i in range(n):
            for j in range(i+1,n):
                if nums[j]>nums[i]: res[i]=nums[j]; break
        return res`,
        javascript: `function solve(nums){const n=nums.length,res=Array(n).fill(-1);for(let i=0;i<n;i++)for(let j=i+1;j<n;j++)if(nums[j]>nums[i]){res[i]=nums[j];break;}return res;}`,
        typescript: `function solve(nums: number[]): number[]{const n=nums.length;const res=Array(n).fill(-1);for(let i=0;i<n;i++)for(let j=i+1;j<n;j++)if(nums[j]>nums[i]){res[i]=nums[j];break;}return res;}`,
        cpp: `class Solution{
public:
    vector<int> solve(vector<int>&nums){int n=nums.size();vector<int>res(n,-1);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(nums[j]>nums[i]){res[i]=nums[j];break;}return res;}
};`,
        java: `class Solution{
    public int[] solve(int[]nums){int n=nums.length;int[]res=new int[n];Arrays.fill(res,-1);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(nums[j]>nums[i]){res[i]=nums[j];break;}return res;}
}`
      }
